import{c as i,$ as n,Q as s,j as r,g as a,o,n as l,m as d}from"./chunks/framework.Ce_49mA8.js";const c="/img/en/front/capital.webp",w=JSON.parse('{"title":"Capital (Management Balance Sheet)","description":"Real-time management balance sheet, net assets, resource allocation structure, and equity control in OmniCraft ERP.","frontmatter":{"title":"Capital (Management Balance Sheet)","description":"Real-time management balance sheet, net assets, resource allocation structure, and equity control in OmniCraft ERP.","datePublished":"2026-08-20","dateModified":"2026-11-14","order":4},"headers":[],"relativePath":"docs/resources/capital.md","filePath":"docs/resources/capital.md","lastUpdated":1794614400000}'),h={name:"docs/resources/capital.md"},u={id:"capital-business-balance-sheet",tabindex:"-1"};function p(g,e,m,f,y,v){const t=n("DocIcon");return s(),r("div",null,[a("h1",u,[o(t,{name:"capital"}),e[0]||(e[0]=l(" Capital: Business Balance Sheet ",-1)),e[1]||(e[1]=a("a",{class:"header-anchor",href:"#capital-business-balance-sheet","aria-label":'Permalink to "Capital: Business Balance Sheet"'},"​",-1))]),e[2]||(e[2]=d('<figure class="doc-image craft-window-frame" data-title="Capital (Balance Sheet) — OmniCraft ERP"><img src="'+c+'" alt="Main window of the Capital tab (Balance Sheet)"><figcaption>Main window of the Capital tab (Balance Sheet)</figcaption></figure><p>The <strong>&quot;Capital&quot;</strong> tab serves as the real-time financial compass for your enterprise. While the Cash Flow ledger (DDS) answers the operational question <em>&quot;Will we have enough cash for tomorrow&#39;s bills?&quot;</em>, the Capital statement answers the founder&#39;s ultimate strategic question:</p><blockquote><p><strong>&quot;What is my entire business genuinely worth right now, if all assets are valued and obligations settled?&quot;</strong></p></blockquote><p>Here, the system consolidates physical machinery, warehouse materials, finished inventory, and available liquidity, deducting outstanding liabilities to determine your <strong>Owner Equity (Net Assets)</strong>.</p><hr><h2 id="mathematical-model-net-asset-equation" tabindex="-1">Mathematical Model: Net Asset Equation <a class="header-anchor" href="#mathematical-model-net-asset-equation" aria-label="Permalink to &quot;Mathematical Model: Net Asset Equation&quot;">​</a></h2><p>The module operates on the fundamental equation of managerial accounting:</p><div class="formula-hero-card"><div class="formula-card-top"><span class="formula-badge">Managerial Balance</span><div class="formula-heading">Owner Equity Equation</div></div><div class="formula-equation-box"><div class="math-line"><span class="math-var">Owner Equity</span><span class="math-op">=</span><span class="math-calc-expr">Total Tangible Assets</span><span class="math-op">−</span><span class="math-calc-expr">Liabilities</span></div></div><div class="formula-card-bottom"><p>Reflects the true net value of your enterprise after deducting liabilities, even when liquid cash is temporarily tight.</p></div></div><p>As long as owner equity remains positive and steadily expands month over month, your enterprise is compounding value, even if liquid cash in your account or cash drawer is temporarily tight.</p><h3 id="conservation-and-circulation-of-value" tabindex="-1">Conservation and Circulation of Value <a class="header-anchor" href="#conservation-and-circulation-of-value" aria-label="Permalink to &quot;Conservation and Circulation of Value&quot;">​</a></h3><p>In everyday life, spending money is often perceived as a loss. In professional accounting within <strong>OmniCraft ERP</strong>, assets undergo continuous transformation:</p><ol><li><strong>Funds Do Not Disappear; They Change State:</strong><ol class="craft-list-steps" style="margin-top:0.8rem;"><li><div><strong>Cash on Hand:</strong><br> Initial liquid capital or received client deposits in the cash ledger. </div></li><li><div><strong>Warehouse Inventory (MAC):</strong><br> Stock purchases and batch intake evaluated via moving average cost. </div></li><li><div><strong>Work in Progress:</strong><br> Component deduction on the workbench and labor hour logging. </div></li><li><div><strong>Finished Goods (FIFO):</strong><br> Completed production booked into stock with permanently frozen unit cost. </div></li><li><div><strong>Cash Return with Net Margin:</strong><br> Customer sale execution, cashier receipt settlement, and profit realization. </div></li></ol></li><li><strong>Depreciation as Investment Recovery:</strong> long-term machinery progressively transfers its book value into the unit cost of products and services via overhead wear rates. These funds return to cash upon sales, building the replacement reserve for capital assets.</li></ol><hr><h2 id="four-balance-sheet-aggregates-asset-breakdown" tabindex="-1">Four Balance Sheet Aggregates (Asset Breakdown) <a class="header-anchor" href="#four-balance-sheet-aggregates-asset-breakdown" aria-label="Permalink to &quot;Four Balance Sheet Aggregates (Asset Breakdown)&quot;">​</a></h2><p>Beneath the primary capital figure, visual progress bars display <strong>in what form</strong> your business capital is currently deployed:</p><h3 id="_1-liquid-cash-treasury" tabindex="-1">1. Liquid Cash (Treasury) <a class="header-anchor" href="#_1-liquid-cash-treasury" aria-label="Permalink to &quot;1. Liquid Cash (Treasury)&quot;">​</a></h3><p>The actual positive cash balance across bank accounts and cash drawers. This is the most agile asset class, ready for immediate raw material orders, tax payments, or owner dividend withdrawals.</p><h3 id="_2-warehouse-materials-and-supplies" tabindex="-1">2. Warehouse Materials and Supplies <a class="header-anchor" href="#_2-warehouse-materials-and-supplies" aria-label="Permalink to &quot;2. Warehouse Materials and Supplies&quot;">​</a></h3><p>The valuation of all on-hand materials calculated using the <strong>Moving Average Cost (MAC)</strong> method. The system accounts for real supplier invoices and freight shipping allocations, reflecting fair warehouse equity.</p><h3 id="_3-finished-goods-and-completed-services" tabindex="-1">3. Finished Goods and Completed Services <a class="header-anchor" href="#_3-finished-goods-and-completed-services" aria-label="Permalink to &quot;3. Finished Goods and Completed Services&quot;">​</a></h3><ul><li>In manufacturing: completed inventory in stock, valued strictly at batch production cost (discharged under the <strong>FIFO method</strong>).</li><li>In the service sector: completed or closing work orders reflecting installed replacement parts and billable technician labor.</li></ul><h3 id="_4-machinery-and-long-term-assets" tabindex="-1">4. Machinery and Long-term Assets <a class="header-anchor" href="#_4-machinery-and-long-term-assets" aria-label="Permalink to &quot;4. Machinery and Long-term Assets&quot;">​</a></h3><p>The residual book value of all active machines, specialized tools, workstations, diagnostic instruments, and shop furnishings after cumulative straight-line depreciation.</p><hr><h2 id="founder-investments-negative-cash-on-the-balance-sheet" tabindex="-1">Founder Investments: Negative Cash on the Balance Sheet <a class="header-anchor" href="#founder-investments-negative-cash-on-the-balance-sheet" aria-label="Permalink to &quot;Founder Investments: Negative Cash on the Balance Sheet&quot;">​</a></h2><p>During business setup or shop expansion, a dedicated line item may appear within the asset breakdown: <strong>&quot;Owner Investments&quot;</strong>.</p><table class="craft-matrix-table"><thead><tr><th style="width:50%;">Balance Sheet Line Item</th><th style="width:25%;">Amount, $</th><th style="width:25%;">Economic Role</th></tr></thead><tbody><tr><td><strong>Machinery &amp; Equipment</strong></td><td>$15,000</td><td>Depreciated book value of fixed assets</td></tr><tr><td><strong>Raw Materials Inventory</strong></td><td>$5,000</td><td>Warehouse materials valued via MAC</td></tr><tr><td><strong>Finished Products in Stock</strong></td><td>$2,000</td><td>Finished batches tracked via FIFO</td></tr><tr><td><strong>Owner Funding (Negative Cash Flow)</strong></td><td>−$7,000</td><td>Founder capital invested into shop launch</td></tr><tr><td><strong>Total Net Capital</strong></td><td><strong>$15,000</strong></td><td><strong>Net equity valuation of the enterprise</strong></td></tr></tbody></table><h3 id="economic-logic-of-founder-capital" tabindex="-1">Economic Logic of Founder Capital: <a class="header-anchor" href="#economic-logic-of-founder-capital" aria-label="Permalink to &quot;Economic Logic of Founder Capital:&quot;">​</a></h3><ul><li>In our mixed finances approach, a negative cash ledger records a verifiable fact: the founder funded tool purchases or shop supplies out of personal funds.</li><li>On the balance sheet, this amount stands as an obligation owed by the enterprise back to the creator.</li><li>Once sales proceeds surpass initial outlays and the Cash Flow balance crosses into positive territory, the Owner Investments line item clears automatically, and subsequent net profits contribute directly to equity expansion.</li></ul><hr><h2 id="balance-sheet-patterns-across-sectors" tabindex="-1">Balance Sheet Patterns Across Sectors <a class="header-anchor" href="#balance-sheet-patterns-across-sectors" aria-label="Permalink to &quot;Balance Sheet Patterns Across Sectors&quot;">​</a></h2><p>While the underlying formula is universal, asset allocation depends directly on your operational model:</p><h3 id="production" tabindex="-1">In Manufacturing and Artisan Crafts <a class="header-anchor" href="#production" aria-label="Permalink to &quot;In Manufacturing and Artisan Crafts {#production}&quot;">​</a></h3><ul><li><strong>Balance Sheet Character:</strong> capital-intensive and inventory-heavy.</li><li><strong>Core Value Centers:</strong> heavy equipment with multi-year lifespans, bulk raw material reserves, and batch goods awaiting dispatch.</li><li><strong>Management Focus:</strong> preventing warehouse stockpiling when finished inventory turnover slows down.</li></ul><h3 id="services" tabindex="-1">In the Service Sector and Repair Centers <a class="header-anchor" href="#services" aria-label="Permalink to &quot;In the Service Sector and Repair Centers {#services}&quot;">​</a></h3><ul><li><strong>Balance Sheet Character:</strong> technician workstations and revolving components.</li><li><strong>Core Value Centers:</strong> diagnostic stations, soldering complexes, lifts, service kits, and active work orders.</li><li><strong>Management Focus:</strong> aligning spare parts inventory with customer service intake volume.</li></ul><h3 id="trade" tabindex="-1">In E-Commerce and Marketplace Sellers <a class="header-anchor" href="#trade" aria-label="Permalink to &quot;In E-Commerce and Marketplace Sellers {#trade}&quot;">​</a></h3><ul><li><strong>Balance Sheet Character:</strong> high-velocity commercial inventory.</li><li><strong>Core Value Centers:</strong> packaged inventory batches, shipping supplies, and compact labeling hardware (thermal printers, barcode scanners).</li><li><strong>Management Focus:</strong> preserving rapid inventory turns without holding stagnant stock keeping units.</li></ul><h3 id="masters" tabindex="-1">For Independent Artisans and Solo Makers <a class="header-anchor" href="#masters" aria-label="Permalink to &quot;For Independent Artisans and Solo Makers {#masters}&quot;">​</a></h3><ul><li><strong>Balance Sheet Character:</strong> lean personal toolkit.</li><li><strong>Core Value Centers:</strong> precision hand tools and a curated working supply of materials without debt burdens.</li><li><strong>Management Focus:</strong> maintaining a transparent boundary between personal savings and workshop capital.</li></ul><hr><h2 id="the-financial-triad-capital-cash-flow-and-analytics" tabindex="-1">The Financial Triad: Capital, Cash Flow, and Analytics <a class="header-anchor" href="#the-financial-triad-capital-cash-flow-and-analytics" aria-label="Permalink to &quot;The Financial Triad: Capital, Cash Flow, and Analytics&quot;">​</a></h2><p>To make sound executive decisions, recognize the roles of the three reporting tools:</p><table tabindex="0"><thead><tr><th style="text-align:left;">Dimension</th><th style="text-align:left;">Cash Flow (DDS)</th><th style="text-align:left;">Capital (Balance Sheet)</th><th style="text-align:left;">Analytics (Profitability)</th></tr></thead><tbody><tr><td style="text-align:left;"><strong>Primary Question</strong></td><td style="text-align:left;">Do we have enough cash for bills tomorrow?</td><td style="text-align:left;">What is the total enterprise worth right now?</td><td style="text-align:left;">What is our margin and revenue trajectory?</td></tr><tr><td style="text-align:left;"><strong>Measurement Method</strong></td><td style="text-align:left;">Physical cash inflows and outflows (cash basis)</td><td style="text-align:left;">All assets, inventory, and goods minus liabilities</td><td style="text-align:left;">Sales velocity, receipt sizes, and line profitability</td></tr><tr><td style="text-align:left;"><strong>Owner Objective</strong></td><td style="text-align:left;">Eliminate cash flow shortages</td><td style="text-align:left;">Grow the net worth of the business</td><td style="text-align:left;">Scale profitable lines and discontinue loss-making items</td></tr></tbody></table><hr><h2 id="five-practical-realities-for-business-owners" tabindex="-1">Five Practical Realities for Business Owners <a class="header-anchor" href="#five-practical-realities-for-business-owners" aria-label="Permalink to &quot;Five Practical Realities for Business Owners&quot;">​</a></h2><p>Mastering balance sheet mechanics protects founders from false assumptions during routine operations:</p><h3 id="reality-1-cash-is-low-yet-the-business-is-wealthier" tabindex="-1">Reality 1: Cash is Low, Yet the Business is Wealthier <a class="header-anchor" href="#reality-1-cash-is-low-yet-the-business-is-wealthier" aria-label="Permalink to &quot;Reality 1: Cash is Low, Yet the Business is Wealthier&quot;">​</a></h3><ul><li><strong>Context:</strong> You spent $2,000 from accounts on a precision CNC laser or purchased a year&#39;s supply of brass fittings at a volume discount.</li><li><strong>In Cash:</strong> Liquid funds appear depleted.</li><li><strong>On the Balance Sheet:</strong> Net equity has not diminished by a cent; with a wholesale discount, it has actually grown. Liquid funds converted into productive machinery that compounds earnings over years.</li></ul><h3 id="reality-2-cash-is-plentiful-yet-capital-is-eroding" tabindex="-1">Reality 2: Cash is Plentiful, Yet Capital is Eroding <a class="header-anchor" href="#reality-2-cash-is-plentiful-yet-capital-is-eroding" aria-label="Permalink to &quot;Reality 2: Cash is Plentiful, Yet Capital is Eroding&quot;">​</a></h3><ul><li><strong>Context:</strong> You ran a clearance sale below unit manufacturing cost to generate quick cash, while shop machinery operates without planned maintenance.</li><li><strong>In Cash:</strong> Temporary liquidity surge.</li><li><strong>On the Balance Sheet:</strong> Equity is deteriorating: warehouses emptied at a net loss, and no depreciation reserve exists to replace aging equipment.</li></ul><h3 id="reality-3-material-scrap-and-natural-wastage" tabindex="-1">Reality 3: Material Scrap and Natural Wastage <a class="header-anchor" href="#reality-3-material-scrap-and-natural-wastage" aria-label="Permalink to &quot;Reality 3: Material Scrap and Natural Wastage&quot;">​</a></h3><ul><li><strong>Context:</strong> Damaged raw material or defective components are discarded under a write-off report.</li><li><strong>Cash Flow Impact:</strong> $0 (no cash leaves the register).</li><li><strong>Capital Impact:</strong> Inventory value decreases by the written-off amount, maintaining a truthful asset valuation.</li></ul><h3 id="reality-4-enterprise-valuation-for-partnerships" tabindex="-1">Reality 4: Enterprise Valuation for Partnerships <a class="header-anchor" href="#reality-4-enterprise-valuation-for-partnerships" aria-label="Permalink to &quot;Reality 4: Enterprise Valuation for Partnerships&quot;">​</a></h3><p>When pitching an investor, negotiating equity splits, or preparing to transfer an operating shop, the Capital tab delivers an audit-ready, documented summary of tangible enterprise worth without inflated speculation.</p><h3 id="reality-5-equity-consolidation-in-pro-mode" tabindex="-1">Reality 5: Equity Consolidation in PRO Mode <a class="header-anchor" href="#reality-5-equity-consolidation-in-pro-mode" aria-label="Permalink to &quot;Reality 5: Equity Consolidation in PRO Mode&quot;">​</a></h3><p>For advanced operations, individual workspace balances synchronize directly into the <strong>&quot;My Capital&quot;</strong> module. There, business balance sheets consolidate alongside personal bank accounts, real estate holdings, investment portfolios, and currency reserves for holistic wealth management.</p><hr><h2 id="financial-hygiene-the-first-of-the-month-review" tabindex="-1">Financial Hygiene: The First-of-the-Month Review <a class="header-anchor" href="#financial-hygiene-the-first-of-the-month-review" aria-label="Permalink to &quot;Financial Hygiene: The First-of-the-Month Review&quot;">​</a></h2><p>Sustained control does not require hours of daily bookkeeping.</p><div class="tip custom-block"><p class="custom-block-title">The First-of-the-Month Rule</p><p>Make it a routine habit to inspect the <strong>&quot;Capital&quot;</strong> tab on the first day of each month and record the headline figure.</p><ul><li>If equity steadily trends upward month over month, your enterprise is compounding strength on a solid foundation.</li><li>If high sales coincide with flat or declining capital, audit warehouse inventory for stagnant stock and verify that equipment wear rates are properly factored into pricing.</li></ul></div><hr><h2 id="troubleshooting-common-pitfalls" tabindex="-1">Troubleshooting &amp; Common Pitfalls <a class="header-anchor" href="#troubleshooting-common-pitfalls" aria-label="Permalink to &quot;Troubleshooting &amp; Common Pitfalls&quot;">​</a></h2><div class="faq-grid"><details class="faq-item"><summary class="faq-summary">Why is equity trending downward despite growing sales volumes?</summary><div class="faq-content"><p>This is a classic symptom of an unrecognized deficit: product prices fail to recover actual material costs, tooling depreciation, or operational overhead. Verify hourly labor wages and audit product recipe cards in the Calculator.</p></div></details><details class="faq-item"><summary class="faq-summary">Why does warehouse valuation in Capital diverge from the latest supplier invoices?</summary><div class="faq-content"><p>OmniCraft ERP values inventory via the moving average cost (MAC) method. If earlier lower-cost stock was on hand, the blended book value of current inventory will be lower than the most recent invoice price.</p></div></details><details class="faq-item"><summary class="faq-summary">How do I record equipment revaluation within the Capital balance?</summary><div class="faq-content"><p>Open the Equipment tab and perform a modernization or revaluation transaction on the asset card. The updated book value automatically refreshes the machinery pillar of your balance sheet without generating fictitious cash flows.</p></div></details></div>',64))])}const q=i(h,[["render",p]]);export{w as __pageData,q as default};
